  public class FileRowView : UniformGrid {
    public FileRowView(){Columns=3;Height=94;DataContextChanged+=delegate {Children.Clear();var row=DataContext as FileRow;if(row==null)return;Columns=row.Entries.Length==0?1:3;Height=row.Entries.Length==0?70:94;if(row.Entries.Length==0){var hint=Ui.Text(L.T("Всё нужное — в одной группе.\nДобавьте файлы или целую папку."),12,Ui.Muted);hint.Foreground=Appearance.BodyInk(row.Owner.Data);hint.Opacity=.75;hint.TextWrapping=TextWrapping.Wrap;hint.Margin=new Thickness(4,10,0,8);Children.Add(hint);}else foreach(var entry in row.Entries)Children.Add(row.Owner.FileTile(entry));};}
  }
