      header=new Border {Height=66,CornerRadius=new CornerRadius(16),Background=Appearance.Header(data),BorderThickness=new Thickness(1),BorderBrush=new SolidColorBrush(Color.FromArgb(90,accent.R,accent.G,accent.B)),Padding=new Thickness(15,0,10,0),Cursor=Cursors.Hand};
      var h=new Grid();h.ColumnDefinitions.Add(new ColumnDefinition {Width=new GridLength(42)});h.ColumnDefinitions.Add(new ColumnDefinition());h.ColumnDefinitions.Add(new ColumnDefinition {Width=new GridLength(32)});h.ColumnDefinitions.Add(new ColumnDefinition {Width=new GridLength(30)});header.Child=h;
      var badge=iconBadge=Ui.Rounded(groupIcon=new Image {Source=Appearance.Icon(main.Data,data),Width=23,Height=23,Stretch=Stretch.Uniform},(accent.R*.2126+accent.G*.7152+accent.B*.0722)<85?"#D5DEEC":"#35435E",11,new Thickness(5));badge.Width=34;badge.Height=36;badge.HorizontalAlignment=HorizontalAlignment.Left;h.Children.Add(badge);var labels=new StackPanel {VerticalAlignment=VerticalAlignment.Center};title=Ui.Text(data.Name,15,Ui.Ink);title.FontWeight=FontWeights.SemiBold;title.TextTrimming=TextTrimming.CharacterEllipsis;count=Ui.Text(L.T("Загрузка…"),11,Ui.Muted);count.Margin=new Thickness(0,3,0,0);labels.Children.Add(title);labels.Children.Add(count);Grid.SetColumn(labels,1);h.Children.Add(labels);var menu=Ui.Button("⋯",OpenMenu,false);menu.Margin=new Thickness(0);menu.Padding=new Thickness(1);menu.Background=Brushes.Transparent;Grid.SetColumn(menu,2);h.Children.Add(menu);arrow=Ui.Text(data.Open?"⌃":"⌄",19,new SolidColorBrush(accent));arrow.HorizontalAlignment=HorizontalAlignment.Center;Grid.SetColumn(arrow,3);h.Children.Add(arrow);header.ToolTip=L.T("Нажатие — открыть / закрыть. Перетаскивание — переместить. ПКМ — меню.");stack.Children.Add(header);
      body=new Border {CornerRadius=new CornerRadius(0,0,16,16),Background=Appearance.Background(data),BorderThickness=new Thickness(1,0,1,1),BorderBrush=Ui.Brush("#34425B"),Margin=new Thickness(5,0,5,0),ClipToBounds=true,Height=data.Open?133:0,Visibility=data.Open?Visibility.Visible:Visibility.Collapsed,Opacity=data.Open?1:0};stack.Children.Add(body);
