    private void ResetHeaderBorder(){header.BorderBrush=Ui.Brush("#5A"+Appearance.Colors[Math.Max(0,Math.Min(29,Data.Color))].Substring(1));}
    private void ReleaseContent(){if(items!=null)items.ClearRows();body.Child=null;items=null;}
