        var entries=new List<FileEntry>();try {foreach(var info in new DirectoryInfo(requested).EnumerateFileSystemInfos())try {bool directory=(info.Attributes&FileAttributes.Directory)!=0;if(PortableLayouts.IsControlEntry(info.FullName))continue;entries.Add(new FileEntry {Path=info.FullName,Directory=directory,Modified=info.LastWriteTimeUtc.Ticks,Length=directory?0:((FileInfo)info).Length});}catch(IOException){}catch(UnauthorizedAccessException){} }catch(IOException){}catch(UnauthorizedAccessException){}
        var ready=entries.OrderBy(e=>e.Directory?0:1).ThenBy(e=>e.Path,StringComparer.CurrentCultureIgnoreCase).ToArray();if(disposed||Dispatcher.HasShutdownStarted)return;try {Dispatcher.BeginInvoke(DispatcherPriority.Background,new Action(delegate {if(disposed)return;scanning=false;if(string.Equals(requested,main.Data.GroupPath(Data),StringComparison.OrdinalIgnoreCase)){bool changed=snapshot==null||snapshot.Length!=ready.Length||!snapshot.Zip(ready,(a,b)=>a.Same(b)).All(s=>s);snapshot=ready;count.Text=L.Items(ready.Length);expandedHeight=ready.Length==0?133:Math.Min(374,((ready.Length+2)/3)*94+66);if(Data.Open){if(changed||items==null)BindRows();body.BeginAnimation(HeightProperty,null);body.Height=expandedHeight;main.ClampCards();}}else scanAgain=true;if(scanAgain){scanAgain=false;LoadItems(false);}}));}catch(InvalidOperationException){}
      });}
    private void EnsureContent(){if(items!=null)return;var content=new Grid();content.RowDefinitions.Add(new RowDefinition());content.RowDefinitions.Add(new RowDefinition {Height=GridLength.Auto});items=new FileViewport {Margin=new Thickness(9,10,9,4)};content.Children.Add(items);var actions=new StackPanel {Orientation=Orientation.Horizontal,Margin=new Thickness(7,2,7,10)};var add=Ui.Button(L.T("+ Файлы"),delegate {main.PickFiles(this);},false);add.Padding=new Thickness(11,6,11,6);var directory=Ui.Button(L.T("+ Папка"),delegate {main.PickFolder(this);},false);directory.Padding=new Thickness(11,6,11,6);actions.Children.Add(add);actions.Children.Add(directory);Grid.SetRow(actions,1);content.Children.Add(actions);body.Child=content;}
    private void BindRows(){EnsureContent();if(snapshot==null)return;var rows=new List<FileRow>();for(int offset=0;offset<snapshot.Length;offset+=3)rows.Add(new FileRow {Owner=this,Entries=snapshot.Skip(offset).Take(3).ToArray()});if(rows.Count==0)rows.Add(new FileRow {Owner=this,Entries=new FileEntry[0]});items.SetRows(rows);}
