    internal void Toggle(){Data.Open=!Data.Open;shownOpen=Data.Open;int version=++toggleVersion;arrow.Text=Data.Open?"⌃":"⌄";double from=body.ActualHeight,target=Data.Open?expandedHeight:0;body.Visibility=Visibility.Visible;body.IsHitTestVisible=Data.Open;if(Data.Open){BindRows();if(snapshot==null)LoadItems(false);}body.BeginAnimation(HeightProperty,null);body.Height=target;var animation=new DoubleAnimation(from,target,TimeSpan.FromMilliseconds(220)){FillBehavior=FillBehavior.Stop,EasingFunction=new CubicEase {EasingMode=EasingMode.EaseOut}};Timeline.SetDesiredFrameRate(animation,45);animation.Completed+=delegate {if(version!=toggleVersion||disposed)return;body.BeginAnimation(HeightProperty,null);if(!Data.Open){body.Visibility=Visibility.Collapsed;ReleaseContent();}};body.BeginAnimation(HeightProperty,animation);Ui.Animate(body,OpacityProperty,Data.Open?0:1,Data.Open?1:0,160);main.ClampCards();main.Save();}
